  function catalogMarkup(name) {
    const catalogName = CATALOG_SYMBOL_NAMES[name];
    if (!catalogName) return "";
    const catalog = window.LocalApp.iconLibrary?.icons || [];
    return catalog.find(function (icon) { return icon.name === catalogName; })?.svg || "";
  }

  function markup(name) {
    return SYMBOLS[name] || catalogMarkup(name);
  }

  function set(target, name) {
    const element = typeof target === "string" ? document.querySelector(target) : target;
    if (!element) return;
    element.dataset.symbol = name;
    element.innerHTML = markup(name);
  }

  function mount(root) {
    (root || document).querySelectorAll("[data-symbol]").forEach(function (element) {
      set(element, element.dataset.symbol);
    });
  }

  window.LocalApp.icons = Object.freeze({
    markup: markup,
    mount: mount,
    set: set
  });
